using System.Collections;
using System.Linq;
using AllAboard.Train;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
namespace AllAboard.Movement.Tests
{
 public sealed class WeaponCombatTests
 {
  private Scene scene;private ProceduralRailway world;private PlayerInteraction actor;private RailwayInventory bag;private Transform aim;
  [UnitySetUp] public IEnumerator Setup(){yield return UnityEditor.SceneManagement.EditorSceneManager.LoadSceneAsyncInPlayMode("Assets/Movement/Scenes/ProceduralRailwayPlayground.unity",new LoadSceneParameters(LoadSceneMode.Additive));yield return null;scene=SceneManager.GetSceneByPath("Assets/Movement/Scenes/ProceduralRailwayPlayground.unity");world=scene.GetRootGameObjects().Select(o=>o.GetComponent<ProceduralRailway>()).First(w=>w!=null);actor=scene.GetRootGameObjects().SelectMany(o=>o.GetComponentsInChildren<PlayerInteraction>()).First();actor.transform.position=new Vector3(0,250,-200);aim=new GameObject("Combat Aim").transform;SceneManager.MoveGameObjectToScene(aim.gameObject,scene);aim.position=actor.transform.position+Vector3.up*1.5f;bag=world.Train.GetComponent<RailwayInventory>();}
  [UnityTearDown] public IEnumerator Cleanup(){if(scene.IsValid()&&scene.isLoaded)yield return SceneManager.UnloadSceneAsync(scene);}
  private WeaponItem Take(WeaponKind kind){var obj=WeaponArt.Create(kind,bag,world.Train.GetComponent<TrainDayEconomy>().Palette);SceneManager.MoveGameObjectToScene(obj,scene);obj.transform.position=aim.position+Vector3.forward*.5f;Assert.That(actor.TryPickup(obj.GetComponent<PickupObject>()),Is.True);return obj.GetComponent<WeaponItem>();}
  private CombatHealth Target(float distance,bool player=false){var obj=GameObject.CreatePrimitive(PrimitiveType.Cube);SceneManager.MoveGameObjectToScene(obj,scene);obj.transform.position=aim.position+aim.forward*distance;var health=obj.AddComponent<CombatHealth>();health.Configure(100,player);Physics.SyncTransforms();return health;}
  [Test] public void EmptyGunCannotShootReloadReservesAndConsumesExactAmmo(){var gun=Take(WeaponKind.Revolver);var target=Target(4);Assert.That(gun.Attack(actor,aim,0),Is.False);bag.AddStock(RailwayProduct.Ammunition,10);Assert.That(gun.Reload(0),Is.True);Assert.That(bag.Stock(RailwayProduct.Ammunition),Is.EqualTo(4));Assert.That(gun.Attack(actor,aim,1),Is.False);gun.FinishReload(3);Assert.That(gun.Loaded,Is.EqualTo(6));Assert.That(gun.Attack(actor,aim,3),Is.True);Assert.That(gun.Loaded,Is.EqualTo(5));Assert.That(target.Health,Is.EqualTo(76));Assert.That(gun.Attack(actor,aim,3.1f),Is.False);}
  [Test] public void DroppingDuringReloadRefundsReservedAmmo(){var gun=Take(WeaponKind.Rifle);bag.AddStock(RailwayProduct.Ammunition,10);gun.Reload(0);Assert.That(bag.Stock(RailwayProduct.Ammunition),Is.EqualTo(5));actor.ReleaseCharged(0);Assert.That(bag.Stock(RailwayProduct.Ammunition),Is.EqualTo(10));Assert.That(gun.Loaded,Is.Zero);}
  [Test] public void FriendlyPlayersCannotBeDamagedByGun(){var gun=Take(WeaponKind.Revolver);bag.AddStock(RailwayProduct.Ammunition,6);gun.Reload(0);gun.FinishReload(3);var player=Target(4,true);Assert.That(gun.Attack(actor,aim,3),Is.True);Assert.That(player.Health,Is.EqualTo(100));Assert.That(player.Damage(50,true),Is.False);}
  [Test] public void WallsBlockGunDamage(){var gun=Take(WeaponKind.Rifle);bag.AddStock(RailwayProduct.Ammunition,5);gun.Reload(0);gun.FinishReload(4);var target=Target(5);var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);SceneManager.MoveGameObjectToScene(wall,scene);wall.transform.position=aim.position+Vector3.forward*2;wall.transform.localScale=new Vector3(3,3,.3f);Physics.SyncTransforms();gun.Attack(actor,aim,4);Assert.That(target.Health,Is.EqualTo(100));}
  [Test] public void MeleeHasLimitedReachAndCannotRepeatBeforeCooldown(){var club=Take(WeaponKind.Club);var target=Target(1.3f);Assert.That(club.Attack(actor,aim,0),Is.True);Assert.That(target.Health,Is.EqualTo(80));Assert.That(club.Attack(actor,aim,.1f),Is.False);target.transform.position=aim.position+Vector3.forward*5;Physics.SyncTransforms();club.Attack(actor,aim,1);Assert.That(target.Health,Is.EqualTo(80));}
  [Test] public void AllWeaponsHaveOneSolidPickupShapeAndClosedVisualParts(){foreach(WeaponKind kind in System.Enum.GetValues(typeof(WeaponKind))){var weapon=WeaponArt.Create(kind,bag,world.Train.GetComponent<TrainDayEconomy>().Palette);SceneManager.MoveGameObjectToScene(weapon,scene);Assert.That(weapon.GetComponentsInChildren<Collider>().Count(c=>c.enabled),Is.EqualTo(1));Assert.That(weapon.GetComponent<PickupObject>(),Is.Not.Null);Assert.That(weapon.GetComponentsInChildren<Renderer>().Length,Is.GreaterThan(4));}}
  [Test] public void OutfitterHasGunsMeleeAmmoAndMedicalButtons(){var shops=world.GetComponentsInChildren<CombatMerchant>();foreach(CombatPurchase item in System.Enum.GetValues(typeof(CombatPurchase)))Assert.That(shops.Any(s=>s.Product==item),Is.True);Assert.That(shops.First(s=>s.Product==CombatPurchase.Ammunition).Price,Is.EqualTo(50));}
  [Test] public void MedicalUseHealsAndConsumesOnlyWhenNeeded(){var obj=MedicalItem.Create(false,world.Train.GetComponent<TrainDayEconomy>().Palette);SceneManager.MoveGameObjectToScene(obj,scene);obj.transform.position=aim.position+Vector3.forward*.5f;actor.TryPickup(obj.GetComponent<PickupObject>());var health=actor.GetComponent<CombatHealth>();Assert.That(obj.GetComponent<MedicalItem>().Use(actor),Is.False);health.Damage(60);Assert.That(obj.GetComponent<MedicalItem>().Use(actor),Is.True);Assert.That(health.Health,Is.EqualTo(75));Assert.That(actor.IsHolding,Is.False);}
  [Test] public void TollRequiresStoppedNearbyTrainAndChargesOnlyOnce(){var encounter=world.GetComponent<CombatWorld>().Encounters.First();int gold=bag.Gold;Assert.That(encounter.Pay(),Is.False);var cars=world.Train.Cars.ToArray();var p=encounter.transform.position;world.Train.Cars[0].transform.position=p-encounter.transform.forward*25;world.Train.Cars[0].Body.position=world.Train.Cars[0].transform.position;Assert.That(encounter.Pay(),Is.True);Assert.That(encounter.State,Is.EqualTo(EncounterState.Paid));Assert.That(bag.Gold,Is.EqualTo(gold-encounter.Toll));Assert.That(encounter.Pay(),Is.False);}
  [Test] public void PassengerHealthRejectsPlayerWeapons(){var friend=Target(4);friend.gameObject.AddComponent<PassengerJourney>();Assert.That(friend.Damage(50,true),Is.False);Assert.That(friend.Health,Is.EqualTo(100));}
  [Test] public void DefeatedBanditDropsSalvageOnlyOnce(){var camp=world.GetComponent<CombatWorld>().Encounters.First();var bandit=camp.GetComponentInChildren<BanditAgent>();var health=bandit.GetComponent<CombatHealth>();int before=camp.GetComponentsInChildren<LootCargo>().Length;Assert.That(health.Damage(1000,true),Is.True);Assert.That(health.Damage(1000,true),Is.False);Assert.That(camp.GetComponentsInChildren<LootCargo>().Length,Is.EqualTo(before+1));Assert.That(bandit.GetComponent<Collider>().enabled,Is.False);}
  [Test] public void EntireCrewDownEndsRunAndSettlesEconomy(){var crew=scene.GetRootGameObjects().SelectMany(o=>o.GetComponentsInChildren<CombatHealth>()).Where(h=>h.IsPlayer).ToArray();Assert.That(crew.Length,Is.GreaterThan(0));foreach(var member in crew)member.Damage(1000);Assert.That(world.DayEnded,Is.True);Assert.That(bag.Settled,Is.True);}
  [Test] public void BanditBodiesDoNotInheritTollInteraction(){var camp=world.GetComponent<CombatWorld>().Encounters.First();foreach(var bandit in camp.GetComponentsInChildren<BanditAgent>())Assert.That(bandit.GetComponent<Collider>().GetComponentInParent<PrototypeInteractable>(),Is.Null);Assert.That(camp.GetComponentInChildren<BanditTollButton>(),Is.Not.Null);}
 }
}
